def count_admissible(m, min_leg, interior_apex):
    # Enumerate points in axial coordinates (i,j) with 0<=i,0<=j,i+j<=m.
    pts = [(i, j) for i in range(m+1) for j in range(m+1-i)]
    n = len(pts)
    # Helper: boundary test
    def is_interior(idx):
        i, j = pts[idx]
        return (i > 0) and (j > 0) and (i + j < m)
    # Squared distance in triangular lattice: for delta (di,dj), d^2 = di^2 + di*dj + dj^2
    def d2(a, b):
        i1, j1 = pts[a]; i2, j2 = pts[b]
        di = i1 - i2; dj = j1 - j2
        return di*di + di*dj + dj*dj
    min_leg2 = min_leg * min_leg
    edges = []
    from itertools import combinations
    for a, b, c in combinations(range(n), 3):
        dab = d2(a, b); dbc = d2(b, c); dca = d2(c, a)
        ok = False
        # Check each isosceles orientation with apex at the vertex of the two equal legs
